  Type Str20     = String[20];
       Str40     = String[40];
       Str80     = String[80];
       StrPtr    = ^String;
       SaveType  = Array[1..4000] Of Byte;
       SavePtr   = ^SaveType;
       ColorSet  = Array[1..2] Of Byte;
       DTColor   = Array[1..3] Of ColorSet;

       MessageWin= Object
                     XMAX,XMIN,
                     YMAX,YMIN : Byte;
                     ID        : Byte;
                     COLOR     : Array[1..3] Of Byte;
                     HL        : Str80;
                     SAVE      : SavePtr;
                     SIZE      : Word;
                     ATTRIBUTES: Record
                                   STYLED : Boolean;
                                   CSIZE  : Word;
                                   X,Y    : Byte;
                                   X1,Y1,
                                   X2,Y2  : Integer;
                                   ATTR   : Byte;
                                 End;
                     CLEARPROC : Procedure;
                     Procedure   AttrSave;
                     Procedure   AttrSet;
                     Constructor Init(X1,Y1,X2,Y2:Byte;C:DTColor;H:Str80);
                     Procedure   Clear; virtual;
                     Procedure   Show;
                     Procedure   Hide;
                     Procedure   Move(X,Y:Byte);
                     Procedure   ReSize(X1,Y1,X2,Y2:Byte);
                     Destructor  Done;
                   End;
       MessageWindow = ^MessageWin;

       Choice     = ^ChoiceRec;
       ChoiceRec  = Record
                      T : Str40;
                      P,N : Choice;
                    End;

       ChoiceWin  = Object(MessageWin)
                      CHOICES : Choice;
                      COUNT   : Word;
                      MAXLEN  : Byte;
                      MAXDISP : Byte;
                      Constructor Init(X1,Y1,X2,Y2:Byte;C:DTColor;H:Str80);
