Implementation
  Var WindowList  : Array[0..255] Of MessageWindow;
      OpenWindows : Byte;
      Regs        : Registers;
      ScreenSave  : ^ScreenType;
      ScreenX,
      ScreenY     : Byte;
      ExitSave    : Pointer;

  Procedure DateObj.On(XPOS,YPOS:Byte);
  Begin
    Disp:=True;
    X:=XPOS;
    Y:=YPOS;
    LD:=0;
  End;

  Procedure DateObj.Off;
  Var I:Byte;
  Begin
    Disp:=False;
    LD:=0;
    AbsWrite(X,Y,'        ');
  End;

  Procedure DateObj.Show;
  Var Year,Month,Day,Dow : Word;
      D                  : String[8];
      I                  : Byte;
  Begin
    If Disp Then
    Begin
      GetDate(Year,Month,Day,Dow);
      If Day=LD Then Exit;
      Dec(Year,(Year Div 100)*100);
      Str(Year:2,D);
      Insert('  /  /',D,1);
      Str(Day:2,D);
      Insert('  /',D,1);
      Str(Month:2,D);
      D[0]:=#8;
      For I:=1 To 8 Do If D[I]=' ' Then D[I]:='0';
      AbsWrite(X,Y,D);
    End;
  End;


  Procedure TimeObj.On(XPOS,YPOS:Byte);
  Begin
    Disp:=True;
    X:=XPOS;
    Y:=YPOS;
  End;

  Procedure TimeObj.Off;
  Var I:Byte;
  Begin
    Disp:=False;
    AbsWrite(X,Y,'           ');
  End;

  Procedure TimeObj.Show;
  Var H,M,S,I:Word;
      T : String[11];
  Begin
    If Disp Then
    Begin
      GetTime(H,M,S,I);
      Str(S:2,T);
      Insert('  :  :',T,1);
      Str(M:2,T);
      Insert('  :',T,1);
      If H>12 Then
      Begin
        H:=H-12;
        Str(H:2,T);
        T[0]:=#8;
        T:=T+' pm';
      End Else
      Begin
        If H<>0 Then
        Begin
          Str(H:2,T);
          T[0]:=#8;
          If H<12 Then T:=T+' am' Else T:=T+' pm';
        End Else
        Begin
          H:=12;
          Str(H:2,T);
          T[0]:=#8;
          T:=T+' am';
        End;
      End;
      For S:=2 To 8 Do If T[S]=' ' Then T[S]:='0';
      AbsWrite(X,Y,T);
    End;
  End;

  Procedure Center(T:String);
  Begin
    GotoXY(Round((Lo(WindMax)-Lo(WindMin)+1)/2-Length(T)/2)+1,WhereY);
    Write(T);
  End;

  Procedure SetColor(C:ColorSet);
  Begin
    TextColor(C[1]);
    TextBackGround(C[2]);
  End;

  Function Bit(B,N:Byte):Boolean;
  Begin
    Bit:=((B shl (15-N)) shr 15)=1;
  End;

  Procedure AbsWrite(X,Y:Byte;S:String);
  Var I : Byte;
  Begin
    For I:=1 To Length(S) Do Screen^[Y,X+I-1].Character:=S[I];
  End;

  Procedure WriteXY(X,Y:Byte;S:String);
  Var I : Byte;
  Begin
    For I:=1 To Length(S) Do
    With WindowList[OpenWindows]^,Screen^[YMIN+Y-1,XMIN+X+I-2] Do
    Begin
      Character:=S[I];
      Attribute:=TextAttr;
    End;
  End;

  Function MakeStr(C:Char;N:Byte):String;
  Var S : String;
      I : Byte;
  Begin
    S:='';
    For I:=1 To N Do S:=S+C;
    MakeStr:=S;
  End;

  Procedure InvChars(X1,X2,Y:Byte);
  Var I:Byte;
  Begin
    Inc(X1,Lo(WindMin));
    Inc(X2,Lo(WindMin));
    Inc(Y,Hi(WindMin));
    For I:=X1 To X2 Do Screen^[Y,I].Attribute:=Screen^[Y,I].Attribute Xor InvByte;
  End;

  Procedure InvLine(Y:Byte);
  Var X1,X2,I : Byte;
  Begin
    If Y=0 Then Exit;
    Inc(Y,Hi(WindMin));
    X1:=Lo(WindMin)+1;
    X2:=Lo(WindMax)+1;
    For I:=X1 To X2 Do Screen^[Y,I].Attribute:=Screen^[Y,I].Attribute Xor InvByte;
  End;

  Procedure VLine(X,Y1,Y2:Byte;C:Char);
  Var I : Byte;
  Begin
    For I:=Y1 To Y2 Do
    Begin
      GotoXY(X,I);
      Write(C);
    End;
  End;

  Procedure HLine(X1,X2,Y:Byte;C:Char);
  Var I : Byte;
  Begin
    GotoXY(X1,Y);
    For I:=X1 To X2 Do Write(C);
  End;

  Procedure Box(X1,Y1,X2,Y2:Byte);
  Var I : Byte;
  Begin
    GotoXY(X1,Y1);
    Write('┌');
    For I:=X1+1 To X2-1 Do Write('─');
    Write('┐');
    For I:=Y1+1 To Y2-1 Do
    Begin
      GotoXY(X1,I);
      Write('│');
      GotoXY(X2,I);
      Write('│');
    End;
    GotoXY(X1,Y2);
    Write('└');
    For I:=X1+1 To X2-1 Do Write('─');
    Write('┘');
  End;

  Procedure Button(X,Y:Byte;T:String);
  Var I : Byte;
  Begin
    GotoXY(X,Y);
    Write('╔');
    For I:=1 To 8 Do Write('═');
    Write('╕');
    GotoXY(X,Y+1);
    Write('║',T:8,'│');
    GotoXY(X,Y+2);
    Write('╙');
    For I:=1 To 8 Do Write('─');
    Write('┘');
  End;

{ *** SwapScreen procedure ************************************************ }

  Procedure SwapScreen(X1,Y1,X2,Y2:Byte;SV:SavePtr);
  Var Y : Byte;
      C : Word;
      L : Word;
      S : String[160];
  Begin
    C:=1;
    L:=(X2-X1+1)*2;
    For Y:=Y1 To Y2 Do
    Begin
      Move(SV^[C],S,L);
      Move(Screen^[Y,X1],SV^[C],L);
      Move(S,Screen^[Y,X1],L);
      Inc(C,L);
    End;
  End;

  Procedure CopyScreen(X1,Y1,X2,Y2:Byte;SV:SavePtr);
  Var Y : Byte;
      C : Word;
      L : Word;
  Begin
    C:=1;
    L:=(X2-X1+1)*2;
    For Y:=Y1 To Y2 Do
    Begin
      Move(Screen^[Y,X1],SV^[C],L);
      Inc(C,L);
    End;
  End;

{ *** Exit procedure ****************************************************** }

  {$F+}
  Procedure NewExit;
  Var I:Byte;
  Begin
    {$F-}
    If (ErrorAddr=Nil) And (ExitCode=0) Then
    Begin
      Move(ScreenSave^,Screen^,4000);
      Window(1,1,80,25);
      GotoXY(ScreenX,ScreenY);
    End;
    Cursor.On;
    NormVideo;
    {$F+}
    ExitProc:=ExitSave;
  End;
  {$F-}

  Procedure SaveScreen;
  Begin
    ScreenX:=WhereX;
    ScreenY:=WhereY;
    New(ScreenSave);
    Move(Screen^,ScreenSave^,4000);
    Window(1,1,80,25);
    ExitSave:=ExitProc;
    ExitProc:=@NewExit;
  End;

{ *** CursorType Methods ************************************************** }

  Procedure CursorType.On;
  Begin
    Regs.CX:=NormSize;
    Regs.AH:=1;
    Intr($10,Regs);
  End;

  Procedure CursorType.Off;
  Begin
    Regs.CX:=$2E00;
    Regs.AH:=1;
    Intr($10,Regs);
  End;

  Procedure CursorType.Full;
  Begin
    Regs.CH:=1;
    Regs.CL:=Lo(NormSize)-1;
    Regs.AH:=1;
    Intr($10,Regs);
  End;

  Procedure CursorType.SetSize(C:Word);
  Begin
    Regs.AH:=1;
    Regs.CX:=C;
    Intr($10,Regs);
  End;

  Function CursorType.GetSize:Word;
  Begin
    Regs.AH:=3;
    Regs.BH:=0;
    Intr($10,Regs);
    GetSize:=Regs.CX;
  End;


  {$F+}
  Procedure NilClear;
  Begin
  End;
