/* Take the top bit of each of four plane bytes into one pixel value. */
char take_plane_pixel(char far *p0, char far *p1, char far *p2, char far *p3)
{
    char pixel = 0;

    if (*p0 & 0x80)
        pixel |= 1;
    if (*p1 & 0x80)
        pixel |= 2;
    if (*p2 & 0x80)
        pixel |= 4;
    if (*p3 & 0x80)
        pixel |= 8;
    *p0 <<= 1;
    *p1 <<= 1;
    *p2 <<= 1;
    *p3 <<= 1;
    return pixel;
}

