    unsigned i, j;

    s = src;
    d = screen_buffer + 0x7d00;
    for (i = 0; i < 8000; i++) {
        *d++ = *s++;
        *d++ = s[7999];
        *d++ = s[15999];
        *d++ = s[23999];
    }
    s = screen_buffer + 0x7d00;
    d = screen_buffer;
    for (i = 0; i < 8000; i++) {
        p0 = *s++;
        p1 = *s++;
        p2 = *s++;
        p3 = *s++;
        for (j = 0; j < 8; j++)
            *d++ = take_plane_pixel(&p0, &p1, &p2, &p3);
    }
}

