// Reader for original Amiga E binary modules ("EMOD", as shipped with
// E v3.3a — the v40 NDK module set). Format reverse-engineered from ECX's
// ecmodtrans.e (ecmod2ecxmod) and validated against real ShowModule output.
//
// Section stream after the EMOD magic, each headed by a 16-bit job code:
//   5 SYS     header: skip 4, osvers.w, skip 4, w, w, skip 2, version.w, skip 4
//   1 CONST   entries: [namelen.w][value.l][name…] until namelen 0
//   2 OBJ     [namelen.w][pad.l][name…] then members
//             [namelen.w][val.w][offset.w][name…] (namelen 0 = private slot)
//             until namelen 0, then [size.w]; v7+ optional method table (skipped)
//   6 LIB     [libname\0][basename\0] then vector entries from -30 step -6:
//             $10 = skipped/zero-arg slot, else [name>0x20…][regbytes<0x10…]
//             where reg 0..7 = D0..D7, 8..15 = A0..A7; $FF ends the section
//   0 DONE
//
// Code modules (e.g. tools/EasyGUI.m) additionally carry:
//   3 CODE    [size.l in LONGWORDS][raw 68k bytes (size*4)]
//   7 RELOC   [count.l][reloc.l * count]; high bit set => "ifunc" reloc
//             (offset = r & $FFFFFF; jsr.l at code+offset-2 that real E patches
//             to bsr.l into the runtime intrinsic table; ifuncNum = code[off+3]-10),
//             else a normal absolute reloc (offset of a 32-bit ptr to rebase)
//   4 PROCS   [namelen.w][name][offset.l][tag.w]; tag 1 = PROC then
//             [narg.w][skip.w][ndefaults.w][defval.l * ndefaults][extra.w][extra],
//             tag 2 = LABEL (offset only). namelen <= 0 ends the section.
//   8 GLOBS   optional SKIPMARK ($8000 word => skip 6); entries until len.w < 0:
//             len > 0 = xref (external symbol: [name (len)] then
//             [coff.l][pad.w(v>=10)]* terminated by coff.l 0),
//             len == 0 = drel (module-private global: same coff list)
//   9 MODINFO / 10 DEBUG / 11 MACROS  — not needed for linking; we stop there
//             (marking partial) once code/procs/relocs/globs are captured.

export function readEmod(buf, name = '<module>') {
  const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const out = {
    name, version: 0, osvers: 0,
    consts: new Map(), objects: new Map(), lib: null,
    // code-module fields (null/empty for pure interface modules):
    code: null, codeWords: 0,
    procs: [],                          // {name, offset, kind:'proc'|'label', args}
    relocs: [],                         // {offset, kind:'abs'|'ifunc', ifuncNum}
    globs: { xrefs: [], drels: [] },    // xrefs:{name,refs[]}  drels:{refs[]}
    globalsCount: 0,
    methods: [],                        // {object, name, offset, args} for class methods
    modinfo: [],                        // cross-module refs: {submodule, symbol, kind, refs:[{coff,type}]}
    isCodeModule: false,
    partial: false, error: null,
  };
  if (buf.length < 6 || String.fromCharCode(buf[0], buf[1], buf[2], buf[3]) !== 'EMOD') {
    out.error = 'not an EMOD file';
    return out;
  }
  let o = 4;
  const end = buf.length;
  const w = () => { const v = dv.getInt16(o, false); o += 2; return v; };
  const sw = w;                                          // signed 16-bit read
  const uw = () => { const v = dv.getUint16(o, false); o += 2; return v; };
  const peekw = () => dv.getUint16(o, false);            // non-advancing
  const l = () => { const v = dv.getInt32(o, false); o += 4; return v; };
  const str = len => {
    let s = '';
    for (let i = 0; i < len && buf[o + i]; i++) s += String.fromCharCode(buf[o + i]);
    o += len;
    return s;
  };

  try {
    while (o < end - 1) {
      const job = uw();
      if (job === 0) break;                      // JOB_DONE
      if (job === 5) {                           // JOB_SYS
        o += 4;
        out.osvers = w();
        o += 4;
        w(); w();
        o += 2;
        out.version = w();
        o += 4;
        if (out.version > 10) o += 4;
      } else if (job === 1) {                    // JOB_CONST
        if (out.version >= 6) o += 4;
        for (;;) {
          const len = uw();
          if (!len) break;
          const value = l();
          const cname = str(len);
          out.consts.set(cname, value);
        }
      } else if (job === 2) {                    // JOB_OBJ
        if (out.version >= 6) o += 4;
        const nlen = uw();
        o += 4;
        const oname = str(nlen);
        const members = new Map();
        let privates = 0;
        for (;;) {
          const mlen = uw();
          if (!mlen) break;
          const val = uw();
          const off = uw();
          if (mlen > 0) {
            const mname = str(mlen);
            members.set(mname, { offset: off, val });
          } else {
            privates++;
          }
          if (out.version >= 6) {
            const c = w();
            if (c < 0) {
              const tlen = uw();
              str(tlen);
            }
          }
        }
        const size = uw();
        const objrec = { name: oname, members, size, privates, methods: [], oacc: [], delcode: null };
        out.objects.set(oname, objrec);
        if (out.version >= 7) {
          // v7+ class trailer (EC WRITEMODULE format). DELSIZE word; if nonzero
          // the object is a class with a method table (vtable). Verified by
          // instruction-tracing real EC output (NEW/dispatch/END), see
          // docs/oop-dispatch.md:
          //   DELCODE.l, SUPERASCLEN.w, ODELOFF.w, ODESTR.w
          //   per method: [TYP.b FL.b][M_OFF.w][ASCLEN.w][name padded]
          //               [NARGS.w][NDEF.w][default.l * NDEF]
          //   methods end on a TYP+FL word == -1
          //   OACC list: [TYP.w][CODE.l]* end on a TYP word == -1
          //
          // The runtime model: a per-class "descriptor" (vtable) of `delsize`
          // bytes is built by calling the module's own code at `delcode` (the
          // builder uses PC-relative LEAs, so no relocs). Layout:
          //   descriptor[0]   = OSIZE (instance byte size = objrec.size)
          //   descriptor[M_OFF] = method code pointer   (M_OFF = 4,8,12,…)
          // An instance is New(OSIZE); instance[0] = descriptor ptr.
          // Dispatch obj.method(): movea (obj)→A0; (A0)→A1; M_OFF(A1)→A1; jsr.
          // `odeloff` = the slot of the destructor method (END obj calls it).
          const delsize = uw();
          if (delsize) {
            objrec.delsize = delsize;          // descriptor (vtable) byte size
            objrec.delcode = l();              // descriptor-BUILDER code offset
            objrec.superasclen = uw();
            objrec.odeloff = uw();             // destructor slot (END obj target)
            objrec.odestr = uw();
            for (;;) {
              const tf = uw();
              if (tf === 0xffff) break;
              const moff = uw();               // M_OFF: vtable slot (NOT code off)
              const asclen = uw();
              const mname = str(asclen);
              const nargs = uw();
              const ndef = uw();
              o += ndef * 4;
              objrec.methods.push({ name: mname, slot: moff, offset: moff, args: nargs,
                kind: tf & 0xff });
              out.methods.push({ object: oname, name: mname, slot: moff, offset: moff, args: nargs });
            }
            // OACC list — "object access": code offsets that reference THIS
            // class's descriptor pointer (same-module self/sibling NEW sites).
            // Each entry is [TYP.w][CODE.l]; CODE is the location of a 16-bit
            // A4 displacement placeholder ($0) the linker binds to the class's
            // descriptor slot. (Cross-module descriptor refs are in MODINFO.)
            for (;;) {
              const typ = uw();
              if (typ === 0xffff) break;
              objrec.oacc.push({ typ, coff: l() >>> 0 });
            }
          }
        }
      } else if (job === 3) {                    // JOB_CODE
        const words = l();
        out.codeWords = words;
        out.code = buf.subarray(o, o + words * 4);
        out.isCodeModule = true;
        o += words * 4;
      } else if (job === 7) {                    // JOB_RELOC
        const count = l();
        for (let i = 0; i < count; i++) {
          const r = l() >>> 0;
          if (r & 0x80000000) {
            const offset = r & 0xffffff;
            // the call site is `jsr.l <…NN>` where the low byte NN is the
            // intrinsic table number (WriteF=10, Mul=11, …) — see ifuncs.js
            const ifuncNum = out.code ? out.code[offset + 3] : null;
            out.relocs.push({ offset, kind: 'ifunc', ifuncNum });
          } else {
            out.relocs.push({ offset: r, kind: 'abs' });
          }
        }
      } else if (job === 4) {                    // JOB_PROCS
        for (;;) {
          const namelen = sw();
          if (namelen <= 0) break;
          const pname = str(namelen);
          const offset = l();
          const tag = uw();
          if (tag === 1) {
            const args = uw();
            uw();                                // skip word
            const ndef = uw();
            // default values for the last `ndef` args (evaluated constants).
            // The caller must push these for any omitted trailing args, else the
            // callee reads its params from misaligned stack offsets.
            const defaults = [];
            for (let i = 0; i < ndef; i++) defaults.push(l());
            const extra = uw();
            o += extra;
            out.procs.push({ name: pname, offset, kind: 'proc', args, ndef, defaults });
          } else if (tag === 2) {
            out.procs.push({ name: pname, offset, kind: 'label', args: 0 });
          } else {
            out.partial = true;
            out.error = `procs: unexpected tag ${tag}`;
            return out;
          }
        }
      } else if (job === 8) {                    // JOB_GLOBS
        if ((peekw() & 0xffff) === 0x8000) o += 6;
        for (;;) {
          const len = sw();
          if (len < 0) break;
          const refs = [];
          const nm = len > 0 ? str(len) : null;
          for (;;) {
            const coff = l();
            if (coff === 0) break;
            if (out.version >= 10) o += 2;       // pad word; LONG refs only
            refs.push(coff);
          }
          if (len > 0) {
            out.globs.xrefs.push({ name: nm, refs });
          } else {
            out.globs.drels.push({ refs });
            out.globalsCount += refs.length;
          }
        }
      } else if (job === 6) {                    // JOB_LIB
        let libname = '';
        while (o < end && buf[o]) libname += String.fromCharCode(buf[o++]);
        o++;
        let basename = '';
        while (o < end && buf[o]) basename += String.fromCharCode(buf[o++]);
        o++;
        const funcs = [];
        let off = -30;
        while (o < end && buf[o] !== 0xff) {
          if (buf[o] === 0x10) { o++; off -= 6; continue; }
          let fname = '';
          while (o < end && buf[o] > 0x20) fname += String.fromCharCode(buf[o++]);
          const regs = [];
          if (buf[o] !== 0x10) {
            while (o < end && buf[o] < 0x10) regs.push(buf[o++]);
          } else {
            o++;
          }
          funcs.push({ name: fname, offset: off, regs });
          off -= 6;
        }
        out.lib = { libname, basename, funcs };
        break;                                   // LIB consumes to end
      } else if (job === 9) {                    // JOB_MODINFO — submodule xref
        // Cross-module references: each imported submodule lists the symbols
        // this module refers to, with the code offsets that need binding to the
        // submodule's symbol. Used for cross-module class inheritance (a child
        // class's .m references its parent class/methods here). Captured into
        // out.modinfo so the linker can resolve them.
        o += 4;                                  // info
        let mlen;
        while ((mlen = uw()) !== 0) {            // submodule name length
          const submodule = str(mlen);
          let sym;
          while ((sym = uw()) !== 0) {           // symbol type
            const idlen = uw();
            const id = str(idlen);
            if (sym === 2) {                     // proc/label: numrefs code-offset longs
              const flag = uw();
              const numrefs = uw();
              const refs = [];
              for (let i = 0; i < numrefs; i++) refs.push({ coff: l() >>> 0, type: 0 });
              out.modinfo.push({ submodule, symbol: id, kind: 'proc', flag, refs });
            } else {                             // class/object etc: naccess [coff.l][type.w]
              const naccess = uw();
              const refs = [];
              for (let i = 0; i < naccess; i++) { const coff = l() >>> 0; const type = uw(); refs.push({ coff, type }); }
              out.modinfo.push({ submodule, symbol: id, kind: sym, refs });
            }
          }
        }
      } else {
        // JOB_DEBUG (10) / MACROS (11) / unknown — not needed for linking;
        // code/procs/relocs/globs/consts/objects are captured before these.
        out.partial = true;
        break;
      }
    }
  } catch (err) {
    out.partial = true;
    out.error = err.message;
  }
  return out;
}

// register byte → register name (0..7 = D0..D7, 8..15 = A0..A7)
export function regName(r) {
  return r < 8 ? `d${r}` : `a${r - 8}`;
}

